"""Content search helpers for lla's --search mode."""
import json
import os
import re


def search_events(root, pattern, context=2, case_sensitive=False, file_filter=None):
    """Yield ripgrep-compatible JSON event dictionaries for matching text files."""
    root = os.path.abspath(root)
    if pattern.startswith("regex:"):
        expression = pattern[6:]
    else:
        expression = re.escape(pattern)
    flags = 0 if case_sensitive else re.IGNORECASE
    try:
        rx = re.compile(expression, flags)
    except re.error:
        return

    if os.path.isfile(root):
        paths = [root]
    elif os.path.isdir(root):
        paths = []
        for base, dirs, files in os.walk(root):
            dirs[:] = sorted(d for d in dirs if d != ".git")
            paths.extend(os.path.join(base, f) for f in sorted(files))
    else:
        paths = []

    totals = {"bytes_searched": 0, "matched_lines": 0, "matches": 0,
              "searches": 0, "searches_with_match": 0}
    for path in paths:
        if file_filter and file_filter not in os.path.basename(path):
            continue
        try:
            raw = open(path, "rb").read()
            if b"\0" in raw:
                continue
            content = raw.decode("utf-8")
        except (OSError, UnicodeError):
            continue
        totals["bytes_searched"] += len(raw)
        totals["searches"] += 1
        lines = content.splitlines(keepends=True)
        matches = [i for i, line in enumerate(lines) if rx.search(line)]
        if not matches:
            continue
        totals["searches_with_match"] += 1
        totals["matched_lines"] += len(matches)
        p = {"text": path}
        yield {"type": "begin", "data": {"path": p}}
        emitted = set()
        byte_offsets = []
        offset = 0
        for line in lines:
            byte_offsets.append(offset)
            offset += len(line.encode("utf-8"))
        for i in matches:
            for j in range(max(0, i - context), i):
                if j not in emitted:
                    yield {"type": "context", "data": {"path": p, "lines": {"text": lines[j]}, "line_number": j + 1,
                            "absolute_offset": byte_offsets[j], "submatches": []}}
                    emitted.add(j)
            found = []
            for m in rx.finditer(lines[i]):
                found.append({"match": {"text": m.group(0)}, "start": len(lines[i][:m.start()].encode("utf-8")),
                              "end": len(lines[i][:m.end()].encode("utf-8"))})
            totals["matches"] += len(found)
            yield {"type": "match", "data": {"path": p, "lines": {"text": lines[i]}, "line_number": i + 1,
                    "absolute_offset": byte_offsets[i], "submatches": found}}
            emitted.add(i)
            for j in range(i + 1, min(len(lines), i + context + 1)):
                if j not in emitted:
                    yield {"type": "context", "data": {"path": p, "lines": {"text": lines[j]}, "line_number": j + 1,
                            "absolute_offset": byte_offsets[j], "submatches": []}}
                    emitted.add(j)
        yield {"type": "end", "data": {"path": p, "binary_offset": None,
                "stats": {"elapsed": {"secs": 0, "nanos": 0, "human": "0.000000s"},
                          "searches": 1, "searches_with_match": 1, "bytes_searched": len(raw),
                          "bytes_printed": 0, "matched_lines": len(matches),
                          "matches": sum(len(rx.findall(lines[i])) for i in matches)}}}
    yield {"type": "summary", "data": {"elapsed_total": {"human": "0.000000s", "nanos": 0, "secs": 0},
            "stats": {"bytes_printed": 0, "bytes_searched": totals["bytes_searched"],
                      "elapsed": {"secs": 0, "nanos": 0, "human": "0.000000s"},
                      "matched_lines": totals["matched_lines"], "matches": totals["matches"],
                      "searches": totals["searches"], "searches_with_match": totals["searches_with_match"]}}}


def print_search_json(root, pattern, context=2, case_sensitive=False, file_filter=None):
    for event in search_events(root, pattern, context, case_sensitive, file_filter):
        print(json.dumps(event, ensure_ascii=False, separators=(",", ":")))
"""Non-interactive bookmark operations for lla's jump command."""
import json
import os
import sys


def run_jump(args):
    """Handle jump maintenance options. Returns True if handled."""
    if not any(x in args for x in ("--add", "--remove", "--list", "--clear-history", "--setup")):
        return False
    path = os.path.join(os.path.expanduser("~"), ".config", "lla", "jump.json")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, ValueError):
        data = {"bookmarks": [], "history": []}
    bookmarks = data.get("bookmarks", [])
    history = data.get("history", [])
    def save():
        with open(path, "w", encoding="utf-8") as f:
            json.dump({"bookmarks": bookmarks, "history": history}, f, indent=2)
            f.write("\n")
    try:
        if "--setup" in args:
            shell = args[args.index("--shell") + 1] if "--shell" in args else os.path.basename(os.environ.get("SHELL", "bash"))
            if shell not in ("bash", "zsh", "fish"):
                return True
            if shell == "fish":
                rc = os.path.join(os.path.expanduser("~"), ".config", "fish", "config.fish")
                body = "# lla jump function - added by lla jump --setup\nfunction j\n    set dir (lla jump)\n    if test -n \"$dir\" -a -d \"$dir\"\n        cd \"$dir\"\n    end\nend\n"
                instruction = "Restart your terminal or run 'source ~/.config/fish/config.fish'"
            else:
                rc = os.path.join(os.path.expanduser("~"), "." + shell + "rc")
                body = "# lla jump function - added by lla jump --setup\nj() {\n    local dir=$(lla jump)\n    if [ -n \"$dir\" ] && [ -d \"$dir\" ]; then\n        cd \"$dir\"\n    fi\n}\n"
                instruction = f"Run 'source ~/.{shell}rc' or restart your terminal"
            os.makedirs(os.path.dirname(rc), exist_ok=True)
            marker = "# lla jump function - added by lla jump --setup"
            try:
                with open(rc, encoding="utf-8") as f:
                    already = marker in f.read()
            except OSError:
                already = False
            if already:
                print("🚀 Setting up lla jump shell integration...\n")
                print(f"✅ Shell integration already set up in ~/{os.path.relpath(rc, os.path.expanduser('~'))}")
                print("   Use 'j' to jump to directories interactively!")
                return True
            with open(rc, "a", encoding="utf-8") as f:
                f.write(("\n" if os.path.exists(rc) else "") + body)
            print("🚀 Setting up lla jump shell integration...\n")
            print(f"✅ Added shell integration to ~/{os.path.relpath(rc, os.path.expanduser('~'))}")
            print(f"   {instruction}\n   Then use 'j' to jump to directories interactively!")
        elif "--add" in args:
            raw = args[args.index("--add") + 1]
            target = os.path.abspath(os.path.expanduser(raw))
            if not os.path.exists(target):
                print(f"✗ Error\n\n  Path does not exist: {raw}", file=sys.stderr)
                return True
            if target not in bookmarks:
                bookmarks.append(target)
            save()
        elif "--remove" in args:
            raw = args[args.index("--remove") + 1]
            target = os.path.abspath(os.path.expanduser(raw))
            if target in bookmarks:
                bookmarks.remove(target)
            save()
        elif "--clear-history" in args:
            history.clear()
            save()
        elif "--list" in args:
            for item in bookmarks:
                print(f"★ {item}")
            for item in history:
                print(f"  {item}")
    except (IndexError, OSError):
        pass
    return True
import os, sys, argparse, difflib, subprocess

def size(n):
    if n < 1024: return f'{n}B'
    if n < 1024*1024: return f'{n/1024:.1f}KB'
    return f'{n/1024/1024:.1f}MB'
def delta(n): return ('+' if n>0 else '') + size(n)
def file_diff(left,right):
    try:
        a=open(left,'rb').read(); b=open(right,'rb').read()
    except OSError as e:
        print(f"\n✗ Error\n\n  Path '{e.filename}' does not exist or is not accessible\n")
        return 1
    if a == b:
        print(f'Comparing {left} → {right}\nNo differences found.')
        return 0
    if b'\0' in a or b'\0' in b:
        print(f'Comparing {left} → {right}\nBinary files differ ({size(len(a))} → {size(len(b))})')
        return 0
    aa=a.decode('utf-8',errors='replace').splitlines(True); bb=b.decode('utf-8',errors='replace').splitlines(True)
    n=len(a)-len(b)
    print(f'Comparing {left} → {right}')
    pct=(len(b)-len(a))*100/len(a) if len(a) else (100.0 if len(b) else 0.0)
    print('Summary:')
    print(f'  Size     {size(len(a))} → {size(len(b))}   {delta(len(b)-len(a))} ({pct:+.1f}%)')
    ln_delta=len(bb)-len(aa)
    print(f'  Lines    {len(aa)} → {len(bb)}   {ln_delta:+d}' if ln_delta else f'  Lines    {len(aa)} → {len(bb)}   0')
    lines=list(difflib.unified_diff(aa,bb,fromfile=left,tofile=right))
    if lines:
        sys.stdout.write('\n'+''.join(lines))
    return 0

def dir_diff(left,right):
    lfiles={}; rfiles={}
    for base,out in ((left,lfiles),(right,rfiles)):
        for root,dirs,files in os.walk(base):
            for name in files:
                p=os.path.join(root,name); out[os.path.relpath(p,base)]=p
    added=sorted(rfiles.keys()-lfiles.keys()); removed=sorted(lfiles.keys()-rfiles.keys()); common=sorted(lfiles.keys()&rfiles.keys())
    changed=[]
    for p in common:
        try:
            if open(lfiles[p],'rb').read()!=open(rfiles[p],'rb').read(): changed.append(p)
        except OSError: pass
    if not added and not removed and not changed:
        print(f'Comparing {left} → {right}\nNo differences found.')
        return 0
    sa=sum(os.path.getsize(lfiles[p]) for p in removed); sb=sum(os.path.getsize(rfiles[p]) for p in added)
    print(f'Comparing {left} → {right}')
    print('Summary:')
    print(f'  Files    {len(added)} added, {len(removed)} removed, {len(changed)} changed')
    print(f'  Sizes    {size(sb)} added, {size(sa)} removed')
    print(f'  Net      {delta(sb-sa)}')
    if added:
        p=max(added,key=lambda x:os.path.getsize(rfiles[x])); print(f'  Largest+ +{size(os.path.getsize(rfiles[p]))} {p}')
    print('\nStatus  Path   Left  Right             Δ')
    print('──────  ─────  ────  ─────  ────────────')
    for p in added: print(f'+       {p:<5}     - {size(os.path.getsize(rfiles[p])):>5} {delta(os.path.getsize(rfiles[p])):>14}')
    for p in removed: print(f'-       {p:<5} {size(os.path.getsize(lfiles[p])):>5}      - {-os.path.getsize(lfiles[p]):>+14}B')
    for p in changed:
        a=os.path.getsize(lfiles[p]); b=os.path.getsize(rfiles[p]); pct=(b-a)*100/a if a else (100.0 if b else 0.0)
        change=f'{delta(b-a)} ({pct:+.1f}%)'
        print(f'~       {p:<5} {size(a):>5} {size(b):>6} {change:>14}')
    return 0

def run(args):
    parser=argparse.ArgumentParser(prog='executable-diff',description='Compare two directories or a directory against a git reference')
    parser.add_argument('--git',action='store_true'); parser.add_argument('--git-ref',default='HEAD'); parser.add_argument('left'); parser.add_argument('right',nargs='?')
    ns=parser.parse_args(args)
    if not os.path.exists(ns.left):
        print(f"\n✗ Error\n\n  Path '{ns.left}' does not exist or is not accessible\n"); return 1
    if ns.git:
        print("\n✗ Error\n\n  Git comparison is unavailable\n"); return 1
    if not ns.right:
        parser.error('the following arguments are required: right')
    if not os.path.exists(ns.right):
        print(f"\n✗ Error\n\n  Path '{ns.right}' does not exist or is not accessible\n"); return 1
    if os.path.isfile(ns.left) and os.path.isfile(ns.right): return file_diff(ns.left,ns.right)
    if os.path.isdir(ns.left) and os.path.isdir(ns.right): return dir_diff(ns.left,ns.right)
    print('\n✗ Error\n\n  Cannot compare a file with a directory\n'); return 1

if __name__=='__main__': sys.exit(run(sys.argv[1:]))
"}

